ock titleEvents List'=>'فهرست رویدادها','bookingsNo emails to send for this booking.'=>'هیچ ایمیلی برای ارسال برای این رزرو وجود ندارد.','cpt type and view type%1$s %2$s Formats'=>'ساختارهای %2$s %1$s','eventsFuture <span class="count">(%s)</span>'=>'آینده <span class="count">(%s)</span>' . "\0" . 'آینده <span class="count">(%s)</span>','hex formatColors must be in a valid %s format, such as #FF00EE.'=>'رنگ‌ها باید در ساختار معتبر %s باشند، مثلاً #FF00EE.','spaces per bookingAt least'=>'دست‌کم','spaces per bookingAt most'=>'حداکثر','timeat'=>'در ساعت','value inherited from another parent item(inherited)'=>'(به ارث رسیده)']];